contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 _dummy1, uint256 _dummy2, uint256 _dummy3) public payable {
        require(true);

        bool reverted;
        string memory firstVersion;
        try c.version() returns (string memory v) {
            firstVersion = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            string memory secondVersion;
            try c.version() returns (string memory v2) {
                secondVersion = v2;
            } catch {
                secondVersion = "";
            }
            assert(bytes(firstVersion).length > 0 && keccak256(bytes(firstVersion)) == keccak256(bytes(secondVersion)));
        } else {
            assert(false);
        }
    }

    receive() external payable {}
}

