contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _numberBefore,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        uint64 _numberAfter
    ) public payable {
        require(_numberAfter != _numberBefore, "number must be changed to observe preservation of other fields");

        bool reverted1;
        try c.setL1BlockValues(
            _numberBefore,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        require(!reverted1, "first setup call must succeed");

        uint64 numberBeforeSecond;
        numberBeforeSecond = c.number();
        require(numberBeforeSecond == _numberBefore, "setup did not set number as expected");

        bool reverted2;
        try c.setL1BlockValues(
            _numberAfter,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        if (reverted2) {
            assert(c.number() == numberBeforeSecond);
        } else {
            assert(c.number() == _numberAfter && c.timestamp() == _timestamp && c.basefee() == _basefee);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _numberBefore,
        uint64 _timestampBefore,
        uint256 _basefeeBefore,
        bytes32 _hashBefore,
        uint64 _sequenceNumberBefore,
        bytes32 _batcherHashBefore,
        uint256 _l1FeeOverheadBefore,
        uint256 _l1FeeScalarBefore,
        uint64 _numberAfter,
        uint64 _timestampAfter,
        uint256 _basefeeAfter,
        bytes32 _hashAfter,
        uint64 _sequenceNumberAfter,
        bytes32 _batcherHashAfter,
        uint256 _l1FeeOverheadAfter,
        uint256 _l1FeeScalarAfter
    ) public payable {
        c.setL1BlockValues(
            _numberBefore,
            _timestampBefore,
            _basefeeBefore,
            _hashBefore,
            _sequenceNumberBefore,
            _batcherHashBefore,
            _l1FeeOverheadBefore,
            _l1FeeScalarBefore
        );

        uint64 numberSnapshot = c.number();
        uint64 timestampSnapshot = c.timestamp();
        uint256 basefeeSnapshot = c.basefee();
        bytes32 hashSnapshot = c.hash();
        uint64 sequenceNumberSnapshot = c.sequenceNumber();
        bytes32 batcherHashSnapshot = c.batcherHash();
        uint256 l1FeeOverheadSnapshot = c.l1FeeOverhead();
        uint256 l1FeeScalarSnapshot = c.l1FeeScalar();

        bool reverted;
        try c.setL1BlockValues(
            _numberAfter,
            _timestampAfter,
            _basefeeAfter,
            _hashAfter,
            _sequenceNumberAfter,
            _batcherHashAfter,
            _l1FeeOverheadAfter,
            _l1FeeScalarAfter
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
                ? (c.number() == numberSnapshot &&
                   c.timestamp() == timestampSnapshot &&
                   c.basefee() == basefeeSnapshot &&
                   c.hash() == hashSnapshot &&
                   c.sequenceNumber() == sequenceNumberSnapshot &&
                   c.batcherHash() == batcherHashSnapshot &&
                   c.l1FeeOverhead() == l1FeeOverheadSnapshot &&
                   c.l1FeeScalar() == l1FeeScalarSnapshot)
                : (c.number() == _numberAfter &&
                   c.timestamp() == _timestampAfter &&
                   c.basefee() == _basefeeAfter &&
                   c.hash() == _hashAfter &&
                   c.sequenceNumber() == _sequenceNumberAfter &&
                   c.batcherHash() == _batcherHashAfter &&
                   c.l1FeeOverhead() == _l1FeeOverheadAfter &&
                   c.l1FeeScalar() == _l1FeeScalarAfter)
        );
    }

    receive() external payable {}
}

